tool(
  "connection_status",
  {
    title: "Connection status",
    description: "Which platforms have keys set (keys themselves are never shown), test each connection, and list the environment variables each platform needs.",
    inputSchema: { test: external_exports.boolean().optional().describe("Also make one read-only call per connected platform.") }
  },
  async ({ test }) => {
    const connected = configuredPlatforms();
    const results = {};
    for (const p of Object.keys(ENV_VARS)) {
      if (!connected.includes(p)) {
        results[p] = {
          connected: false,
          howToConnect: `Run /plugin configure crm-lifecycle-ops and fill in the ${p} fields (in other MCP clients: set ${ENV_VARS[p].required.map((v) => `CLO_${v}`).join(" and ")}).`
        };
        continue;
      }
      if (!test) {
        results[p] = { connected: true, workspace: workspaceFor(p) };
        continue;
      }
      try {
        results[p] = { connected: true, workspace: workspaceFor(p), check: await getAdapter(p).ping() };
      } catch (e) {
        results[p] = { connected: false, workspace: workspaceFor(p), error: e.message };
      }
    }
    return json2(results);
  }
);
tool(
  "refresh_account",
  {
    title: "Refresh account snapshot",
    description: "Pull the latest campaigns, journeys, segments, templates and content blocks into a local snapshot (read-only API calls), then report what changed since the previous one. Set demo: true to load the fictional Fernbrook Market demo account instead.",
    inputSchema: { platform: platformArg, demo: external_exports.boolean().optional() }
  },
  async ({ platform, demo }) => {
    try {
      let snap;
      if (demo) {
        if (platform !== "braze") return fail("The demo account is a Braze workspace; use platform: braze.");
        snap = demoSnapshot();
      } else {
        const adapter = getAdapter(platform);
        const { latest: prev2 } = await loadLatest(platform, adapter.workspace);
        snap = await adapter.snapshot(prev2);
      }
      const { latest: prev } = await loadLatest(platform, snap.workspace);
      carryForwardSeenAudiences(prev, snap);
      const file2 = await saveSnapshot(snap);
      const changes = prev ? diffSnapshots(prev, snap) : [];
      await logRun({ tool: "refresh_account", platform });
      return json2({
        workspace: snap.workspace,
        savedTo: file2,
        counts: {
          campaigns: snap.campaigns.length,
          liveCampaigns: snap.campaigns.filter((c) => isActive(c.status)).length,
          journeys: snap.journeys.length,
          liveJourneys: snap.journeys.filter((j) => isActive(j.status)).length,
          messages: snap.messages.length,
          segmentsAndLists: snap.segments.length,
          contentBlocks: snap.contentBlocks.length
        },
        gaps: snap.gaps,
        changesSincePrevious: prev ? changes.slice(0, 30) : "first snapshot"
      });
    } catch (e) {
      return fail(e.message);
    }
  }
);
tool(
  "list_items",
  {
    title: "Find campaigns, journeys, segments or blocks",
    description: "Search the latest snapshot by name. Use it to resolve what the person means before checking, mapping or analysing impact.",
    inputSchema: {
      platform: platformArg,
      workspace: workspaceArg,
      kind: external_exports.enum(["campaign", "journey", "segment", "content-block", "message", "all"]).optional(),
      query: external_exports.string().optional(),
      active_only: external_exports.boolean().optional(),
      limit: external_exports.number().int().positive().max(500).optional().describe("Max results per kind (default 50).")
    }
  },
  async ({ platform, workspace, kind = "all", query, active_only, limit = 50 }) => {
    const snap = await latest(platform, workspace);
    const q = (query ?? "").toLowerCase();
    const match = (name) => name.toLowerCase().includes(q);
    const out = { snapshotTakenAt: snap.takenAt, limitPerKind: limit };
    const cap = (xs) => xs.slice(0, limit);
    if (kind === "all" || kind === "campaign")
      out.campaigns = cap(
        snap.campaigns.filter((c) => match(c.name) && (!active_only || isActive(c.status))).map(({ id, name, status: status2, channels }) => ({ id, name, status: status2, channels }))
      );
    if (kind === "all" || kind === "journey")
      out.journeys = cap(
        snap.journeys.filter((j) => match(j.name) && (!active_only || isActive(j.status))).map(({ id, name, status: status2, steps }) => ({ id, name, status: status2, steps: steps.length }))
      );
    if (kind === "all" || kind === "segment")
      out.segments = cap(
        snap.segments.filter((s) => match(s.name)).map(({ id, name, kind: k, description }) => ({ id, name, kind: k, description }))
      );
    if (kind === "all" || kind === "content-block")
      out.contentBlocks = cap(
        snap.contentBlocks.filter((b) => match(b.name)).map(({ id, name, usedBy }) => ({ id, name, usedIn: usedBy.length }))
      );
    if (kind === "message")
      out.messages = cap(
        snap.messages.filter((m) => match(m.name) || match(m.subject ?? "")).map(({ id, name, subject, ownerId }) => ({ id, name, subject, ownerId }))
      );
    return json2(out);
  }
);
tool(
  "record_audience",
  {
    title: "Record an audience seen on screen",
    description: "Fill an API gap: record which segment/list a campaign or journey targets, as read from the platform's dashboard (e.g. via Claude in Chrome). Stored as 'seen-on-screen' with today's date on the latest snapshot.",
    inputSchema: {
      platform: platformArg,
      workspace: workspaceArg,
      item: external_exports.string().describe("Campaign or journey name or id."),
      segment: external_exports.string().describe("Segment or list name or id."),
      mode: external_exports.enum(["include", "exclude"]).optional()
    }
  },
  async ({ platform, workspace, item, segment, mode = "include" }) => {
    const snap = await latest(platform, workspace);
    const found = findItem(snap, item);
    if ("candidates" in found)
      return fail(`Couldn't pin down "${item}". ${found.near ? "Did you mean" : "Candidates"}: ${found.candidates.join("; ") || "none"}`);
    const seg = snap.segments.find((s) => s.id === segment || s.name.toLowerCase() === segment.toLowerCase());
    if (!seg) return fail(`No segment or list called "${segment}" in the snapshot. Run /refresh if it's new.`);
    found.item.audience = [
      ...found.item.audience.filter((a) => a.confidence !== "unknown"),
      { id: seg.id, kind: seg.kind, mode, confidence: "seen-on-screen", seenAt: (/* @__PURE__ */ new Date()).toISOString() }
    ];
    await updateLatest(snap);
    return json2({ recorded: true, item: found.item.name, audience: found.item.audience });
  }
);
